public enum AppEvent: Codable, Sendable, Hashable {
    case dataChanged(store: StoreKind, tables: [String], ids: [String], origin: String)
    case saveState(SaveState)
    case projectOpened(projectId: String)
    case projectClosed(projectId: String)
    case task(TaskProgress)
    case module(module: String, name: String, payload: JSONValue)

    private enum CodingKeys: String, CodingKey {
        case ids
        case module
        case name
        case origin
        case payload
        case projectId
        case store
        case tables
        case type
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .type)
        switch tag {
        case "dataChanged":
            self = .dataChanged(store: try c.decode(StoreKind.self, forKey: .store), tables: try c.decode([String].self, forKey: .tables), ids: try c.decode([String].self, forKey: .ids), origin: try c.decode(String.self, forKey: .origin))
        case "saveState":
            self = .saveState(try SaveState(from: decoder))
        case "projectOpened":
            self = .projectOpened(projectId: try c.decode(String.self, forKey: .projectId))
        case "projectClosed":
            self = .projectClosed(projectId: try c.decode(String.self, forKey: .projectId))
        case "task":
            self = .task(try TaskProgress(from: decoder))
        case "module":
            self = .module(module: try c.decode(String.self, forKey: .module), name: try c.decode(String.self, forKey: .name), payload: try c.decode(JSONValue.self, forKey: .payload))
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown type \(tag) for AppEvent"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .dataChanged(let a0, let a1, let a2, let a3):
            try c.encode("dataChanged", forKey: .type)
            try c.encode(a0, forKey: .store)
            try c.encode(a1, forKey: .tables)
            try c.encode(a2, forKey: .ids)
            try c.encode(a3, forKey: .origin)
        case .saveState(let payload):
            try c.encode("saveState", forKey: .type)
            try payload.encode(to: encoder)
        case .projectOpened(let a0):
            try c.encode("projectOpened", forKey: .type)
            try c.encode(a0, forKey: .projectId)
        case .projectClosed(let a0):
            try c.encode("projectClosed", forKey: .type)
            try c.encode(a0, forKey: .projectId)
        case .task(let payload):
            try c.encode("task", forKey: .type)
            try payload.encode(to: encoder)
        case .module(let a0, let a1, let a2):
            try c.encode("module", forKey: .type)
            try c.encode(a0, forKey: .module)
            try c.encode(a1, forKey: .name)
            try c.encode(a2, forKey: .payload)
        }
    }
}

