/// Where "Buy full version" took the user.
public enum BuyRoute: Codable, Sendable, Hashable {
    case store
    case unavailable

    private enum CodingKeys: String, CodingKey {
        case route
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .route)
        switch tag {
        case "store":
            self = .store
        case "unavailable":
            self = .unavailable
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown route \(tag) for BuyRoute"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .store:
            try c.encode("store", forKey: .route)
        case .unavailable:
            try c.encode("unavailable", forKey: .route)
        }
    }
}

