/// What the app knows about the user's right to use it.
public enum EntitlementState: Codable, Sendable, Hashable {
    case trialActive(days_left: Double)
    case trialEnded
    case purchased
    case revoked
    case unknown
    case needsOnlineCheck
    case trialNotStarted
    case internalBuild

    private enum CodingKeys: String, CodingKey {
        case days_left
        case state
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .state)
        switch tag {
        case "trialActive":
            self = .trialActive(days_left: try c.decode(Double.self, forKey: .days_left))
        case "trialEnded":
            self = .trialEnded
        case "purchased":
            self = .purchased
        case "revoked":
            self = .revoked
        case "unknown":
            self = .unknown
        case "needsOnlineCheck":
            self = .needsOnlineCheck
        case "trialNotStarted":
            self = .trialNotStarted
        case "internalBuild":
            self = .internalBuild
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown state \(tag) for EntitlementState"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .trialActive(let a0):
            try c.encode("trialActive", forKey: .state)
            try c.encode(a0, forKey: .days_left)
        case .trialEnded:
            try c.encode("trialEnded", forKey: .state)
        case .purchased:
            try c.encode("purchased", forKey: .state)
        case .revoked:
            try c.encode("revoked", forKey: .state)
        case .unknown:
            try c.encode("unknown", forKey: .state)
        case .needsOnlineCheck:
            try c.encode("needsOnlineCheck", forKey: .state)
        case .trialNotStarted:
            try c.encode("trialNotStarted", forKey: .state)
        case .internalBuild:
            try c.encode("internalBuild", forKey: .state)
        }
    }
}

