/// The screen the app shows now. At most one at a time, in the order of [`due`].
public enum Notice: Codable, Sendable, Hashable {
    case none_
    case reminder(daysLeft: Double)
    case dataNote
    case tutorial
    case welcome
    case macFirstLaunch
    case locked
    case checkNeeded

    private enum CodingKeys: String, CodingKey {
        case daysLeft
        case kind
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .kind)
        switch tag {
        case "none":
            self = .none_
        case "reminder":
            self = .reminder(daysLeft: try c.decode(Double.self, forKey: .daysLeft))
        case "dataNote":
            self = .dataNote
        case "tutorial":
            self = .tutorial
        case "welcome":
            self = .welcome
        case "macFirstLaunch":
            self = .macFirstLaunch
        case "locked":
            self = .locked
        case "checkNeeded":
            self = .checkNeeded
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown kind \(tag) for Notice"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .none_:
            try c.encode("none", forKey: .kind)
        case .reminder(let a0):
            try c.encode("reminder", forKey: .kind)
            try c.encode(a0, forKey: .daysLeft)
        case .dataNote:
            try c.encode("dataNote", forKey: .kind)
        case .tutorial:
            try c.encode("tutorial", forKey: .kind)
        case .welcome:
            try c.encode("welcome", forKey: .kind)
        case .macFirstLaunch:
            try c.encode("macFirstLaunch", forKey: .kind)
        case .locked:
            try c.encode("locked", forKey: .kind)
        case .checkNeeded:
            try c.encode("checkNeeded", forKey: .kind)
        }
    }
}

