/// `manifest.json`: the package metadata required by Import/Export §9.3.
public struct PackageManifest: Codable, Sendable, Hashable {
    public var format: String
    public var packageType: PackageType
    public var formatVersion: Double
    public var packageId: String
    public var sourceProjectId: String
    public var sourceProjectTitle: String
    public var exportedAt: Double
    public var appVersion: String
    /// Project database schema version (backup / full project packages).
    public var schemaVersion: Double?
    public var sourceDraft: PackageSourceDraft?
    public var sourceVersions: [PackageSourceVersion]
    public var includedObjectIds: [String]
    public var scope: PackageScope
    public var commentsIncluded: Bool
    public var attachmentsIncluded: Bool
    /// Always false for exchange packages (Security §8.6).
    public var privateNotesIncluded: Bool
    /// Row revisions of the included objects at export time (`table:id` → rev),
    /// used to detect stale packages and conflicts.
    public var baseSnapshot: [String: Double]
    public var originatingUser: PackageUser
    /// Optional user label (backup naming, FSD §44.8).
    public var label: String?
    /// Response packages: the review package this responds to.
    public var respondsTo: PackageRef?
    /// Format 2, backup and full project packages: live row count of every project table at
    /// export time. Restore refuses a database whose counts differ. Empty in format 1.
    public var tableCounts: [String: Double]
    /// Format 2, exchange packages: the `table.column` values the writer carried (see
    /// `coverage`). A reader treats a field missing from this list as not sent rather than
    /// empty. Empty in format 1.
    public var carried: [String]

    public init(format: String, packageType: PackageType, formatVersion: Double, packageId: String, sourceProjectId: String, sourceProjectTitle: String, exportedAt: Double, appVersion: String, schemaVersion: Double? = nil, sourceDraft: PackageSourceDraft? = nil, sourceVersions: [PackageSourceVersion], includedObjectIds: [String], scope: PackageScope, commentsIncluded: Bool, attachmentsIncluded: Bool, privateNotesIncluded: Bool, baseSnapshot: [String: Double], originatingUser: PackageUser, label: String? = nil, respondsTo: PackageRef? = nil, tableCounts: [String: Double], carried: [String]) {
        self.format = format
        self.packageType = packageType
        self.formatVersion = formatVersion
        self.packageId = packageId
        self.sourceProjectId = sourceProjectId
        self.sourceProjectTitle = sourceProjectTitle
        self.exportedAt = exportedAt
        self.appVersion = appVersion
        self.schemaVersion = schemaVersion
        self.sourceDraft = sourceDraft
        self.sourceVersions = sourceVersions
        self.includedObjectIds = includedObjectIds
        self.scope = scope
        self.commentsIncluded = commentsIncluded
        self.attachmentsIncluded = attachmentsIncluded
        self.privateNotesIncluded = privateNotesIncluded
        self.baseSnapshot = baseSnapshot
        self.originatingUser = originatingUser
        self.label = label
        self.respondsTo = respondsTo
        self.tableCounts = tableCounts
        self.carried = carried
    }
}

