/// One element-level edit. Ops are applied in order; indexes refer to the
/// state after the previous ops (the editor computes them that way).
public enum ScreenplayEditOp: Codable, Sendable, Hashable {
    case insertElement(id: String?, sceneId: String, index: Double?, elementType: ElementType, text: String, customElementId: String?)
    case updateElement(id: String, elementType: ElementType?, text: String?, customElementId: String?)
    case deleteElement(id: String)
    case moveElement(id: String, sceneId: String, index: Double?)
    case insertScene(id: String?, index: Double?, heading: String)
    case updateScene(id: String, heading: String)
    case moveScene(id: String, index: Double)
    case deleteScene(id: String)
    case splitScene(elementId: String, newSceneId: String?)
    case mergeScene(sceneId: String)

    private enum CodingKeys: String, CodingKey {
        case customElementId
        case elementId
        case elementType
        case heading
        case id
        case index
        case newSceneId
        case op
        case sceneId
        case text
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .op)
        switch tag {
        case "insertElement":
            self = .insertElement(id: try c.decodeIfPresent(String.self, forKey: .id), sceneId: try c.decode(String.self, forKey: .sceneId), index: try c.decodeIfPresent(Double.self, forKey: .index), elementType: try c.decode(ElementType.self, forKey: .elementType), text: try c.decode(String.self, forKey: .text), customElementId: try c.decodeIfPresent(String.self, forKey: .customElementId))
        case "updateElement":
            self = .updateElement(id: try c.decode(String.self, forKey: .id), elementType: try c.decodeIfPresent(ElementType.self, forKey: .elementType), text: try c.decodeIfPresent(String.self, forKey: .text), customElementId: try c.decodeIfPresent(String.self, forKey: .customElementId))
        case "deleteElement":
            self = .deleteElement(id: try c.decode(String.self, forKey: .id))
        case "moveElement":
            self = .moveElement(id: try c.decode(String.self, forKey: .id), sceneId: try c.decode(String.self, forKey: .sceneId), index: try c.decodeIfPresent(Double.self, forKey: .index))
        case "insertScene":
            self = .insertScene(id: try c.decodeIfPresent(String.self, forKey: .id), index: try c.decodeIfPresent(Double.self, forKey: .index), heading: try c.decode(String.self, forKey: .heading))
        case "updateScene":
            self = .updateScene(id: try c.decode(String.self, forKey: .id), heading: try c.decode(String.self, forKey: .heading))
        case "moveScene":
            self = .moveScene(id: try c.decode(String.self, forKey: .id), index: try c.decode(Double.self, forKey: .index))
        case "deleteScene":
            self = .deleteScene(id: try c.decode(String.self, forKey: .id))
        case "splitScene":
            self = .splitScene(elementId: try c.decode(String.self, forKey: .elementId), newSceneId: try c.decodeIfPresent(String.self, forKey: .newSceneId))
        case "mergeScene":
            self = .mergeScene(sceneId: try c.decode(String.self, forKey: .sceneId))
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown op \(tag) for ScreenplayEditOp"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .insertElement(let a0, let a1, let a2, let a3, let a4, let a5):
            try c.encode("insertElement", forKey: .op)
            try c.encodeIfPresent(a0, forKey: .id)
            try c.encode(a1, forKey: .sceneId)
            try c.encodeIfPresent(a2, forKey: .index)
            try c.encode(a3, forKey: .elementType)
            try c.encode(a4, forKey: .text)
            try c.encodeIfPresent(a5, forKey: .customElementId)
        case .updateElement(let a0, let a1, let a2, let a3):
            try c.encode("updateElement", forKey: .op)
            try c.encode(a0, forKey: .id)
            try c.encodeIfPresent(a1, forKey: .elementType)
            try c.encodeIfPresent(a2, forKey: .text)
            try c.encodeIfPresent(a3, forKey: .customElementId)
        case .deleteElement(let a0):
            try c.encode("deleteElement", forKey: .op)
            try c.encode(a0, forKey: .id)
        case .moveElement(let a0, let a1, let a2):
            try c.encode("moveElement", forKey: .op)
            try c.encode(a0, forKey: .id)
            try c.encode(a1, forKey: .sceneId)
            try c.encodeIfPresent(a2, forKey: .index)
        case .insertScene(let a0, let a1, let a2):
            try c.encode("insertScene", forKey: .op)
            try c.encodeIfPresent(a0, forKey: .id)
            try c.encodeIfPresent(a1, forKey: .index)
            try c.encode(a2, forKey: .heading)
        case .updateScene(let a0, let a1):
            try c.encode("updateScene", forKey: .op)
            try c.encode(a0, forKey: .id)
            try c.encode(a1, forKey: .heading)
        case .moveScene(let a0, let a1):
            try c.encode("moveScene", forKey: .op)
            try c.encode(a0, forKey: .id)
            try c.encode(a1, forKey: .index)
        case .deleteScene(let a0):
            try c.encode("deleteScene", forKey: .op)
            try c.encode(a0, forKey: .id)
        case .splitScene(let a0, let a1):
            try c.encode("splitScene", forKey: .op)
            try c.encode(a0, forKey: .elementId)
            try c.encodeIfPresent(a1, forKey: .newSceneId)
        case .mergeScene(let a0):
            try c.encode("mergeScene", forKey: .op)
            try c.encode(a0, forKey: .sceneId)
        }
    }
}

