public enum StoryItem: Codable, Sendable, Hashable {
    case sequence(StorySequenceDto)
    case beat(StoryBeatDto)
    case card(StorySceneCardDto)

    private enum CodingKeys: String, CodingKey {
        case kind
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .kind)
        switch tag {
        case "sequence":
            self = .sequence(try StorySequenceDto(from: decoder))
        case "beat":
            self = .beat(try StoryBeatDto(from: decoder))
        case "card":
            self = .card(try StorySceneCardDto(from: decoder))
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown kind \(tag) for StoryItem"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .sequence(let payload):
            try c.encode("sequence", forKey: .kind)
            try payload.encode(to: encoder)
        case .beat(let payload):
            try c.encode("beat", forKey: .kind)
            try payload.encode(to: encoder)
        case .card(let payload):
            try c.encode("card", forKey: .kind)
            try payload.encode(to: encoder)
        }
    }
}

