/// Which slice of the vault to show (left panel selection).
public enum VaultView: Codable, Sendable, Hashable {
    case all
    case pinned
    case recentlyAdded
    case recentlyModified
    case folder(folderId: String?)
    case collection(collectionId: String)
    case tag(tag: String)

    private enum CodingKeys: String, CodingKey {
        case collectionId
        case folderId
        case kind
        case tag
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .kind)
        switch tag {
        case "all":
            self = .all
        case "pinned":
            self = .pinned
        case "recentlyAdded":
            self = .recentlyAdded
        case "recentlyModified":
            self = .recentlyModified
        case "folder":
            self = .folder(folderId: try c.decodeIfPresent(String.self, forKey: .folderId))
        case "collection":
            self = .collection(collectionId: try c.decode(String.self, forKey: .collectionId))
        case "tag":
            self = .tag(tag: try c.decode(String.self, forKey: .tag))
        default:
            throw DecodingError.dataCorrupted(DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unknown kind \(tag) for VaultView"))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .all:
            try c.encode("all", forKey: .kind)
        case .pinned:
            try c.encode("pinned", forKey: .kind)
        case .recentlyAdded:
            try c.encode("recentlyAdded", forKey: .kind)
        case .recentlyModified:
            try c.encode("recentlyModified", forKey: .kind)
        case .folder(let a0):
            try c.encode("folder", forKey: .kind)
            try c.encodeIfPresent(a0, forKey: .folderId)
        case .collection(let a0):
            try c.encode("collection", forKey: .kind)
            try c.encode(a0, forKey: .collectionId)
        case .tag(let a0):
            try c.encode("tag", forKey: .kind)
            try c.encode(a0, forKey: .tag)
        }
    }
}

